//! Wave 5b.1 iter 1 — chunk-parallel inter-chunk state-recurrence kernel.
//!
//! Spec source:
//! - arXiv 2412.06464 §4 (Yang–Hatamizadeh; chunkwise parallelization)
//! - FLA reference: `chunk_gated_delta_rule_fwd_kernel_h_blockdim64` at
//!   /opt/vllm/vllm/model_executor/layers/fla/ops/chunk_delta_h.py:43-298
//!
//! The reference fixture is generated by the deterministic PyTorch port at
//! `tests/fixtures/gated_delta_net_chunk_reference.py`. To regenerate:
//!
//! ```sh
//! python3 tests/fixtures/gated_delta_net_chunk_reference.py
//! ```
//!
//! Tolerance bar: `bf16 atol = 5e-3, rtol = 2e-2` for the bf16 outputs (`h`
//! and `v_new`); same bar for the f32 final-state output. This matches the
//! `flash_attn_prefill_d512` bf16 tolerance bar (see
//! `flash_attn_prefill_d512.metal:21`).

#![allow(clippy::expect_used, clippy::unwrap_used, clippy::panic)]

use std::fs;
use std::path::PathBuf;

use mlx_native::ops::gated_delta_net_chunk::{
    build_gated_delta_net_chunk_params, dispatch_gated_delta_net_chunk_inter_state,
    GatedDeltaNetChunkParams,
};
use mlx_native::{DType, KernelRegistry, MlxBuffer, MlxDevice};

// ---------------------------------------------------------------------------
// Fixture metadata — must match `gated_delta_net_chunk_reference.py`.
// ---------------------------------------------------------------------------
const B: u32 = 1;
const T: u32 = 128;
const HG: u32 = 2;
const H: u32 = 4;
const K: u32 = 128;
const V: u32 = 128;
const BT: u32 = 64;
const NT: u32 = T / BT;

fn fixture_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures")
}

fn read_bytes(name: &str) -> Vec<u8> {
    let path = fixture_dir().join(name);
    fs::read(&path).unwrap_or_else(|e| {
        panic!(
            "failed to read fixture {} — did you run `python3 tests/fixtures/gated_delta_net_chunk_reference.py`? ({})",
            path.display(),
            e
        )
    })
}

fn read_f32(name: &str) -> Vec<f32> {
    let bytes = read_bytes(name);
    assert!(bytes.len() % 4 == 0, "f32 byte length not multiple of 4");
    let mut out = Vec::with_capacity(bytes.len() / 4);
    for chunk in bytes.chunks_exact(4) {
        out.push(f32::from_le_bytes([chunk[0], chunk[1], chunk[2], chunk[3]]));
    }
    out
}

fn bf16_bytes_to_f32(bytes: &[u8]) -> Vec<f32> {
    assert!(bytes.len() % 2 == 0, "bf16 byte length not multiple of 2");
    let mut out = Vec::with_capacity(bytes.len() / 2);
    for chunk in bytes.chunks_exact(2) {
        // bf16 = upper 16 bits of f32, padded with 16 low zeros.
        let bf16 = u16::from_le_bytes([chunk[0], chunk[1]]);
        let bits = (bf16 as u32) << 16;
        out.push(f32::from_bits(bits));
    }
    out
}

fn upload_bf16(device: &MlxDevice, bytes: &[u8]) -> MlxBuffer {
    let n_elems = bytes.len() / 2;
    let mut buf = device
        .alloc_buffer(bytes.len(), DType::BF16, vec![n_elems])
        .expect("alloc bf16");
    let dst = buf.as_mut_slice::<u8>().expect("mut bytes");
    dst.copy_from_slice(bytes);
    buf
}

fn upload_f32(device: &MlxDevice, data: &[f32]) -> MlxBuffer {
    let mut buf = device
        .alloc_buffer(data.len() * 4, DType::F32, vec![data.len()])
        .expect("alloc f32");
    buf.as_mut_slice::<f32>()
        .expect("mut")
        .copy_from_slice(data);
    buf
}

fn alloc_zeroed_bf16(device: &MlxDevice, n_elems: usize) -> MlxBuffer {
    let mut buf = device
        .alloc_buffer(n_elems * 2, DType::BF16, vec![n_elems])
        .expect("alloc bf16");
    let dst = buf.as_mut_slice::<u8>().expect("mut bytes");
    dst.fill(0u8);
    buf
}

// ---------------------------------------------------------------------------
// The TDD test — exercises the actual GPU kernel against the FLA reference.
// ---------------------------------------------------------------------------
#[test]
fn test_chunk_inter_state_matches_fla_reference_bf16() {
    let device = MlxDevice::new().expect("MlxDevice::new");
    let mut registry = KernelRegistry::new();

    // Inputs — loaded from the Python-generated fixture.
    let k_bytes = read_bytes("gated_delta_net_chunk_input_k.bin");
    let w_bytes = read_bytes("gated_delta_net_chunk_input_w.bin");
    let u_bytes = read_bytes("gated_delta_net_chunk_input_u.bin");
    let g_vals = read_f32("gated_delta_net_chunk_input_g.bin");
    let h0_vals = read_f32("gated_delta_net_chunk_input_h0.bin");

    let expected_k_elems = (B * T * HG * K) as usize;
    let expected_w_elems = (B * T * H * K) as usize;
    let expected_u_elems = (B * T * H * V) as usize;
    let expected_g_elems = (B * T * H) as usize;
    let expected_h0_elems = (B * H * V * K) as usize;
    assert_eq!(k_bytes.len(), expected_k_elems * 2, "k size mismatch");
    assert_eq!(w_bytes.len(), expected_w_elems * 2, "w size mismatch");
    assert_eq!(u_bytes.len(), expected_u_elems * 2, "u size mismatch");
    assert_eq!(g_vals.len(), expected_g_elems, "g size mismatch");
    assert_eq!(h0_vals.len(), expected_h0_elems, "h0 size mismatch");

    let k_buf = upload_bf16(&device, &k_bytes);
    let w_buf = upload_bf16(&device, &w_bytes);
    let u_buf = upload_bf16(&device, &u_bytes);
    let g_buf = upload_f32(&device, &g_vals);
    let h0_buf = upload_f32(&device, &h0_vals);

    // Output buffers.
    let h_out_elems = (B * NT * H * V * K) as usize;
    let v_new_elems = (B * T * H * V) as usize;
    let final_elems = (B * H * V * K) as usize;

    let h_out_buf = alloc_zeroed_bf16(&device, h_out_elems);
    let v_new_buf = alloc_zeroed_bf16(&device, v_new_elems);
    let final_buf = upload_f32(&device, &vec![0.0f32; final_elems]);

    let p = GatedDeltaNetChunkParams {
        b: B,
        t: T,
        hg: HG,
        h: H,
        k: K,
        v: V,
        bt: BT,
    };
    let params_buf = build_gated_delta_net_chunk_params(&device, p).expect("params");

    let mut enc = device.command_encoder().expect("enc");
    dispatch_gated_delta_net_chunk_inter_state(
        &mut enc,
        &mut registry,
        device.metal_device(),
        &k_buf,
        &w_buf,
        &u_buf,
        &g_buf,
        &h0_buf,
        &h_out_buf,
        &v_new_buf,
        &final_buf,
        &params_buf,
        p,
    )
    .expect("dispatch");
    enc.commit_and_wait().expect("commit");

    // Read back outputs.
    let h_out_bytes = h_out_buf.as_slice::<u8>().expect("read h").to_vec();
    let v_new_bytes = v_new_buf.as_slice::<u8>().expect("read v_new").to_vec();
    let final_vec = final_buf.as_slice::<f32>().expect("read final").to_vec();

    let got_h = bf16_bytes_to_f32(&h_out_bytes);
    let got_v_new = bf16_bytes_to_f32(&v_new_bytes);

    // Reference.
    let ref_h_bytes = read_bytes("gated_delta_net_chunk_state_ref.bin");
    let ref_v_new_bytes = read_bytes("gated_delta_net_chunk_v_new_ref.bin");
    let ref_final = read_f32("gated_delta_net_chunk_final_ref.bin");
    let ref_h = bf16_bytes_to_f32(&ref_h_bytes);
    let ref_v_new = bf16_bytes_to_f32(&ref_v_new_bytes);

    assert_eq!(got_h.len(), ref_h.len(), "h length mismatch");
    assert_eq!(got_v_new.len(), ref_v_new.len(), "v_new length mismatch");
    assert_eq!(final_vec.len(), ref_final.len(), "final length mismatch");

    let atol: f32 = 5e-3;
    let rtol: f32 = 2e-2;

    let mut max_h_err = 0.0f32;
    let mut max_v_err = 0.0f32;
    let mut max_f_err = 0.0f32;

    for (i, (&g, &r)) in got_h.iter().zip(ref_h.iter()).enumerate() {
        let abs_err = (g - r).abs();
        let rel_err = abs_err / r.abs().max(f32::EPSILON);
        max_h_err = max_h_err.max(abs_err);
        if abs_err > atol && rel_err > rtol {
            panic!(
                "h[{}]: gpu={} ref={} abs_err={} rel_err={}",
                i, g, r, abs_err, rel_err
            );
        }
    }
    for (i, (&g, &r)) in got_v_new.iter().zip(ref_v_new.iter()).enumerate() {
        let abs_err = (g - r).abs();
        let rel_err = abs_err / r.abs().max(f32::EPSILON);
        max_v_err = max_v_err.max(abs_err);
        if abs_err > atol && rel_err > rtol {
            panic!(
                "v_new[{}]: gpu={} ref={} abs_err={} rel_err={}",
                i, g, r, abs_err, rel_err
            );
        }
    }
    for (i, (&g, &r)) in final_vec.iter().zip(ref_final.iter()).enumerate() {
        let abs_err = (g - r).abs();
        let rel_err = abs_err / r.abs().max(f32::EPSILON);
        max_f_err = max_f_err.max(abs_err);
        if abs_err > atol && rel_err > rtol {
            panic!(
                "final[{}]: gpu={} ref={} abs_err={} rel_err={}",
                i, g, r, abs_err, rel_err
            );
        }
    }

    eprintln!(
        "chunk_inter_state OK   max_h_err={:.3e}   max_v_err={:.3e}   max_final_err={:.3e}",
        max_h_err, max_v_err, max_f_err
    );
}

// ---------------------------------------------------------------------------
// Sanity: zero inputs => zero outputs (the kernel is connected and wired).
// ---------------------------------------------------------------------------
#[test]
fn test_chunk_inter_state_zero_inputs_yield_zero() {
    let device = MlxDevice::new().expect("MlxDevice::new");
    let mut registry = KernelRegistry::new();

    let k_elems = (B * T * HG * K) as usize;
    let w_elems = (B * T * H * K) as usize;
    let u_elems = (B * T * H * V) as usize;
    let g_elems = (B * T * H) as usize;
    let h0_elems = (B * H * V * K) as usize;
    let h_out_elems = (B * NT * H * V * K) as usize;
    let v_new_elems = (B * T * H * V) as usize;
    let final_elems = (B * H * V * K) as usize;

    let k_buf = alloc_zeroed_bf16(&device, k_elems);
    let w_buf = alloc_zeroed_bf16(&device, w_elems);
    let u_buf = alloc_zeroed_bf16(&device, u_elems);
    let g_buf = upload_f32(&device, &vec![0.0f32; g_elems]);
    let h0_buf = upload_f32(&device, &vec![0.0f32; h0_elems]);

    let h_out_buf = alloc_zeroed_bf16(&device, h_out_elems);
    let v_new_buf = alloc_zeroed_bf16(&device, v_new_elems);
    let final_buf = upload_f32(&device, &vec![0.0f32; final_elems]);

    let p = GatedDeltaNetChunkParams {
        b: B,
        t: T,
        hg: HG,
        h: H,
        k: K,
        v: V,
        bt: BT,
    };
    let params_buf = build_gated_delta_net_chunk_params(&device, p).expect("params");

    let mut enc = device.command_encoder().expect("enc");
    dispatch_gated_delta_net_chunk_inter_state(
        &mut enc,
        &mut registry,
        device.metal_device(),
        &k_buf,
        &w_buf,
        &u_buf,
        &g_buf,
        &h0_buf,
        &h_out_buf,
        &v_new_buf,
        &final_buf,
        &params_buf,
        p,
    )
    .expect("dispatch");
    enc.commit_and_wait().expect("commit");

    let h_out_bytes = h_out_buf.as_slice::<u8>().expect("read h");
    let v_new_bytes = v_new_buf.as_slice::<u8>().expect("read v_new");
    let final_vec = final_buf.as_slice::<f32>().expect("read final");

    assert!(
        h_out_bytes.iter().all(|&b| b == 0),
        "h_out should be all-zero with zero inputs"
    );
    assert!(
        v_new_bytes.iter().all(|&b| b == 0),
        "v_new should be all-zero with zero inputs"
    );
    assert!(
        final_vec.iter().all(|&v| v == 0.0),
        "final_state should be all-zero with zero inputs"
    );
}

/// Every SIMDgroup must finish reading the old state before any scales it.
/// With h0=1, w=1/K and u=k=0, the first chunk has the exact oracle
/// v_new=-1 and h_out=1, regardless of exp's implementation. Nonzero g
/// makes an early in-place state scale observable to a lagging reader.
#[test]
fn test_chunk_inter_state_nonzero_state_read_before_scale() {
    use mlx_native::ops::chunk_gated_delta_rule_bank_split::dispatch_chunk_inter_state_k256;

    let device = MlxDevice::new().expect("MlxDevice::new");
    let mut registry = KernelRegistry::new();
    for head_dim in [128u32, 256] {
        let p = GatedDeltaNetChunkParams {
            b: B,
            t: T,
            hg: HG,
            h: H,
            k: head_dim,
            v: V,
            bt: BT,
        };
        let k_buf = alloc_zeroed_bf16(&device, (B * T * HG * head_dim) as usize);
        let w_elems = (B * T * H * head_dim) as usize;
        let w_bits = ((1.0f32 / head_dim as f32).to_bits() >> 16) as u16;
        let w_bytes: Vec<u8> = (0..w_elems).flat_map(|_| w_bits.to_le_bytes()).collect();
        let w_buf = upload_bf16(&device, &w_bytes);
        let value_elems = (B * T * H * V) as usize;
        let u_buf = alloc_zeroed_bf16(&device, value_elems);
        let g_buf = upload_f32(&device, &vec![-1.0; (B * T * H) as usize]);
        let state_elems = (B * H * V * head_dim) as usize;
        let h0_buf = upload_f32(&device, &vec![1.0; state_elems]);
        let h_out_buf = alloc_zeroed_bf16(&device, state_elems * NT as usize);
        let v_new_buf = alloc_zeroed_bf16(&device, value_elems);
        let final_buf = upload_f32(&device, &vec![0.0; state_elems]);
        let params_buf = build_gated_delta_net_chunk_params(&device, p).expect("params");
        let mut baseline: Option<[Vec<u8>; 3]> = None;

        for trial in 0..8 {
            let mut enc = device.command_encoder().expect("enc");
            let dispatch = if head_dim == 128 {
                dispatch_gated_delta_net_chunk_inter_state
            } else {
                dispatch_chunk_inter_state_k256
            };
            dispatch(
                &mut enc,
                &mut registry,
                device.metal_device(),
                &k_buf,
                &w_buf,
                &u_buf,
                &g_buf,
                &h0_buf,
                &h_out_buf,
                &v_new_buf,
                &final_buf,
                &params_buf,
                p,
            )
            .expect("dispatch");
            enc.commit_and_wait().expect("commit");
            if trial == 0 {
                let label = if head_dim == 128 {
                    "gated_delta_net_chunk_inter_state_bf16"
                } else {
                    "gated_delta_net_chunk_inter_state_bf16_k256"
                };
                eprintln!(
                    "chunk_state_pipeline {}",
                    serde_json::to_string(
                        &registry.pipeline_identity(label).expect("pipeline identity")
                    )
                    .expect("serialize pipeline identity")
                );
            }

            let h_bytes = h_out_buf.as_slice::<u8>().expect("read h");
            let v_bytes = v_new_buf.as_slice::<u8>().expect("read v_new");
            let final_values = final_buf.as_slice::<f32>().expect("read final");
            for (i, value) in bf16_bytes_to_f32(&h_bytes[..state_elems * 2])
                .into_iter()
                .enumerate()
            {
                assert_eq!(
                    value.to_bits(), 1.0f32.to_bits(),
                    "K={head_dim} trial={trial} first-chunk h[{i}]"
                );
            }
            let first_chunk_values = (BT * H * V) as usize;
            for (i, value) in bf16_bytes_to_f32(&v_bytes[..first_chunk_values * 2])
                .into_iter()
                .enumerate()
            {
                assert_eq!(
                    value.to_bits(), (-1.0f32).to_bits(),
                    "K={head_dim} trial={trial} first-chunk v_new[{i}] read scaled state"
                );
            }
            assert!(
                final_values.iter().all(|value| value.is_finite() && *value > 0.0),
                "K={head_dim} trial={trial} final state must be finite and nonzero"
            );
            let current = [
                h_bytes.to_vec(),
                v_bytes.to_vec(),
                final_buf.as_slice::<u8>().expect("read final bytes").to_vec(),
            ];
            if let Some(expected) = &baseline {
                for (name, (actual, expected)) in ["h", "v_new", "final_state"]
                    .into_iter()
                    .zip(current.iter().zip(expected.iter()))
                {
                    assert!(
                        actual == expected,
                        "K={head_dim} trial={trial} reused {name} must be byte-identical"
                    );
                }
            } else {
                baseline = Some(current);
            }
        }
    }
}

/// Independent exact recurrence oracle for the K=256 V16 layout. Values vary
/// across batches, heads, BT rows, V16 boundaries, and all 32 K tiles.
/// Sparse w selects one old-state cell; k updates every K cell only at each
/// chunk's first timestep. Thus each dot has one nonzero product, eliminating
/// reduction-order ambiguity while exercising both MMA phases and chunk two.
#[test]
fn test_chunk_inter_state_k256_v16_layout_matches_exact_recurrence() {
    use mlx_native::ops::chunk_gated_delta_rule_bank_split::dispatch_chunk_inter_state_k256;

    let batches = 2usize;
    let time = T as usize;
    let heads = H as usize;
    let key_heads = HG as usize;
    let keys = 256usize;
    let values = V as usize;
    let chunk = BT as usize;
    let chunks = time / chunk;
    let state_index = |b: usize, h: usize, v: usize, k: usize| {
        ((b * heads + h) * values + v) * keys + k
    };
    let value_index = |b: usize, t: usize, h: usize, v: usize| {
        ((b * time + t) * heads + h) * values + v
    };
    let round_bf16 = |value: f32| {
        let bits = value.to_bits();
        f32::from_bits((bits + 0x7fff + ((bits >> 16) & 1)) & 0xffff0000)
    };
    let bf16_bytes = |data: &[f32]| -> Vec<u8> {
        data.iter()
            .flat_map(|value| ((value.to_bits() >> 16) as u16).to_le_bytes())
            .collect()
    };

    let mut k_input = vec![0.0f32; batches * time * key_heads * keys];
    let mut w_input = vec![0.0f32; batches * time * heads * keys];
    let mut u_input = vec![0.0f32; batches * time * heads * values];
    let mut initial_state = vec![0.0f32; batches * heads * values * keys];
    for b in 0..batches {
        for t in 0..time {
            if t % chunk == 0 {
                for kh in 0..key_heads {
                    for k in 0..keys {
                        k_input[((b * time + t) * key_heads + kh) * keys + k] =
                            (1 + b + kh + k % 7) as f32 / 64.0;
                    }
                }
            }
            for h in 0..heads {
                let selected_k = (t * 17 + h * 31) % keys;
                w_input[((b * time + t) * heads + h) * keys + selected_k] = 1.0 / 16.0;
                for v in 0..values {
                    u_input[value_index(b, t, h, v)] =
                        (1 + b * 3 + h * 5 + t % 17 + v % 31 + v / 16) as f32 / 256.0;
                }
            }
        }
        for h in 0..heads {
            for v in 0..values {
                for k in 0..keys {
                    initial_state[state_index(b, h, v, k)] =
                        (1 + b * 7 + h * 11 + v % 19 + v / 16 + k % 23) as f32 / 256.0;
                }
            }
        }
    }

    let mut expected_state = initial_state.clone();
    let mut expected_h = vec![0.0f32; batches * chunks * heads * values * keys];
    let mut expected_v = vec![0.0f32; u_input.len()];
    for b in 0..batches {
        for c in 0..chunks {
            let start = c * chunk;
            for h in 0..heads {
                let kh = h / (heads / key_heads);
                for v in 0..values {
                    for k in 0..keys {
                        let out = (((b * chunks + c) * heads + h) * values + v) * keys + k;
                        expected_h[out] = round_bf16(expected_state[state_index(b, h, v, k)]);
                    }
                    // All rows read the same chunk-start state, not a state
                    // updated by an earlier timestep within this chunk.
                    for t in start..start + chunk {
                        let selected_k = (t * 17 + h * 31) % keys;
                        let old = expected_state[state_index(b, h, v, selected_k)];
                        let out = value_index(b, t, h, v);
                        expected_v[out] = round_bf16(u_input[out] - old / 16.0);
                    }
                    let first_v = expected_v[value_index(b, start, h, v)];
                    for k in 0..keys {
                        let index = state_index(b, h, v, k);
                        let coefficient = k_input[((b * time + start) * key_heads + kh) * keys + k];
                        // BF16 × BF16 is exact in F32, so this matches the
                        // sole nonzero outer-update MMA product plus old bh.
                        expected_state[index] += first_v * coefficient;
                    }
                }
            }
        }
    }

    let device = MlxDevice::new().expect("MlxDevice::new");
    let mut registry = KernelRegistry::new();
    let k_buf = upload_bf16(&device, &bf16_bytes(&k_input));
    let w_buf = upload_bf16(&device, &bf16_bytes(&w_input));
    let u_buf = upload_bf16(&device, &bf16_bytes(&u_input));
    let g_buf = upload_f32(&device, &vec![0.0; batches * time * heads]);
    let h0_buf = upload_f32(&device, &initial_state);
    let h_buf = alloc_zeroed_bf16(&device, expected_h.len());
    let v_buf = alloc_zeroed_bf16(&device, expected_v.len());
    let final_buf = upload_f32(&device, &vec![0.0; expected_state.len()]);
    let p = GatedDeltaNetChunkParams {
        b: batches as u32,
        t: T,
        hg: HG,
        h: H,
        k: keys as u32,
        v: V,
        bt: BT,
    };
    let params = build_gated_delta_net_chunk_params(&device, p).expect("params");
    let mut encoder = device.command_encoder().expect("encoder");
    dispatch_chunk_inter_state_k256(
        &mut encoder, &mut registry, device.metal_device(),
        &k_buf, &w_buf, &u_buf, &g_buf, &h0_buf,
        &h_buf, &v_buf, &final_buf, &params, p,
    )
    .expect("K256 V16 dispatch");
    encoder.commit_and_wait().expect("K256 V16 commit");
    eprintln!(
        "chunk_state_pipeline {}",
        serde_json::to_string(
            &registry
                .pipeline_identity("gated_delta_net_chunk_inter_state_bf16_k256")
                .expect("pipeline identity")
        )
        .expect("serialize pipeline identity")
    );

    let got_h = bf16_bytes_to_f32(h_buf.as_slice::<u8>().expect("read h"));
    let got_v = bf16_bytes_to_f32(v_buf.as_slice::<u8>().expect("read v_new"));
    let got_state = final_buf.as_slice::<f32>().expect("read final state");
    for (name, got, expected) in [
        ("h", got_h.as_slice(), expected_h.as_slice()),
        ("v_new", got_v.as_slice(), expected_v.as_slice()),
        ("final_state", got_state, expected_state.as_slice()),
    ] {
        assert_eq!(got.len(), expected.len(), "{name} length");
        for (i, (&actual, &expected)) in got.iter().zip(expected).enumerate() {
            assert_eq!(
                actual.to_bits(), expected.to_bits(),
                "K256 V16 {name}[{i}]: got={actual} expected={expected}"
            );
        }
    }
}

/// Wave 5b.2 iter-1.5 regression: K=192 must be rejected by validate().
///
/// Codex iter-1 audit caught that section 2f's simdgroup_matrix MMA loop
/// hard-codes 16 K-tiles (K=128/8). Generalizing to runtime `K/8u` defeats
/// Metal's MMA scheduler (measured 3.15× regression, 1.08 → 3.40 ms), so
/// MAX_K is narrowed to 128 to match the kernel's compile-time tile count.
/// This test asserts the contract narrowing — K=192 dispatch must error
/// rather than silently corrupting cols 128..191.
#[test]
fn test_chunk_inter_state_k192_rejected_by_validate() {
    use mlx_native::ops::gated_delta_net_chunk::MAX_K;
    assert_eq!(MAX_K, 128, "MAX_K narrowed to 128 in Wave 5b.2 iter 1.5");

    // Try to dispatch at K=192 and observe the validate-side rejection.
    let device = MlxDevice::new().expect("MlxDevice::new");
    let mut registry = KernelRegistry::new();

    const K_192: u32 = 192;
    let k_elems = (B * T * HG * K_192) as usize;
    let w_elems = (B * T * H * K_192) as usize;
    let u_elems = (B * T * H * V) as usize;
    let g_elems = (B * T * H) as usize;
    let h0_elems = (B * H * V * K_192) as usize;
    let h_out_elems = (B * NT * H * V * K_192) as usize;
    let v_new_elems = (B * T * H * V) as usize;
    let final_elems = (B * H * V * K_192) as usize;

    let k_buf = alloc_zeroed_bf16(&device, k_elems);
    let w_buf = alloc_zeroed_bf16(&device, w_elems);
    let u_buf = alloc_zeroed_bf16(&device, u_elems);
    let g_buf = upload_f32(&device, &vec![0.0f32; g_elems]);
    let h0_buf = upload_f32(&device, &vec![0.0f32; h0_elems]);
    let h_out_buf = alloc_zeroed_bf16(&device, h_out_elems);
    let v_new_buf = alloc_zeroed_bf16(&device, v_new_elems);
    let final_buf = upload_f32(&device, &vec![0.0f32; final_elems]);

    let p = GatedDeltaNetChunkParams {
        b: B,
        t: T,
        hg: HG,
        h: H,
        k: K_192,
        v: V,
        bt: BT,
    };
    let params_buf = build_gated_delta_net_chunk_params(&device, p).expect("params");

    let mut enc = device.command_encoder().expect("enc");
    let result = dispatch_gated_delta_net_chunk_inter_state(
        &mut enc,
        &mut registry,
        device.metal_device(),
        &k_buf,
        &w_buf,
        &u_buf,
        &g_buf,
        &h0_buf,
        &h_out_buf,
        &v_new_buf,
        &final_buf,
        &params_buf,
        p,
    );
    let err = result.expect_err("K=192 dispatch must error");
    let msg = err.to_string();
    assert!(
        msg.contains("192") && (msg.contains("MAX_K") || msg.contains("threadgroup")),
        "expected K=192-rejection error citing MAX_K or threadgroup budget, got: {msg}"
    );
}
